library = read('audit/source-notes.json')
for key, url, locator, evidence in SOURCES:
    limitation = 'Institutional text inspected; no film/video playback claimed.'
    if 'springfieldspringfield' in url or 'imsdb' in url:
        limitation = 'Third-party mirror/transcription of film dialogue or screenplay; no playback claimed. Related institutional profiles and corroboration are recorded separately.'
    elif 'wikipedia' in url:
        limitation = 'Secondary plot/cast account; official profiles or original-dialogue evidence provide corroboration where recorded. No playback claimed.'
    elif key == 'basil':
        limitation = 'Contemporary Brian Sibley film review reproduced by DIX; not a studio synopsis. Exact address is explicit in the reproduced review.'
    elif key.startswith('weenie'):
        limitation = 'Secondary account of the design vocabulary with a John Hench quotation/book locator; original book not accessed. Wording asks usage, not invention priority.'
    library['sources']['b25-' + key] = dict(url=url, locator=locator, evidence=evidence, checkedBy='Codex', checkedAt='2026-11-08', timeSensitive=key in {'presidents','nemoport','america','thunderfl','thunderca'}, nextReviewAt='2027-02-06' if key in {'presidents','nemoport','america','thunderfl','thunderca'} else None, limitations=limitation, topics=['Batch 25',key])
write('audit/source-notes.json', library)

