checks = ['singleAnswer','context','wording','noGiveaway','distinctFact','category','difficulty','scope']
used = set()
result = []
for qid, keys, premise, reasons, challenge in ROWS:
    r = templates[qid]
    ids = [key[1:] if key.startswith('@') else 'b25-' + key for key in keys.split()]
    used.update(ids)
    r.update(checks=checks.copy(), notes='All four final options reviewed; full matching topic digests and cross-bank context read. ' + challenge, context='Named original Disney/Pixar film, or the explicitly named park/historical setting. ' + premise, timeSensitive=qid in {1355,1362,1365,1367}, nextReviewAt='2027-02-06' if qid in {1355,1362,1365,1367} else None)
    r['premise'] = dict(reason=premise, sources=ids)
    r['options'] = [dict(basis='direct' if i==0 else 'exclusive-inference', reason=reason, sources=ids) for i,reason in enumerate(reasons)]
    # Literal contradictions and complete two-host lists are stronger than names.
    if qid == 1339:
        r['options'][3]['basis'] = 'contradiction'
    if qid == 1365:
        for option in r['options'][1:]: option['basis']='exhaustive-list'
    if qid == 1359:
        for option in r['options'][1:]: option['basis']='contradiction'
    if qid == 1355:
        r['nextReviewAt'] = '2027-02-04'
    r['challenge'] = dict(reviewer='Codex',at='2026-11-08',premiseChecked=True,alternativesExcluded=True,notes=challenge)
    result.append(r)
assert set(templates) == {r['questionId'] for r in result}
notes.update(sourcesChecked=sorted(used), reviews=result)
write('audit/runs/next-shard-0025-final-notes.json', notes)
